def generate(site,origin):
 meta=json.loads((Path(__file__).resolve().parents[1]/'docs/page-metadata.json').read_text())
 def url(slug='',hi=False):return origin+('/hi/' if hi else '/')+(slug+'/' if slug else '')
 def nav(hi):return '<nav class="page-links" aria-label="'+('साइट पेज' if hi else 'Website pages')+'">'+''.join(f'<a href="{url(slug,hi)}">{esc(hindi if hi else label)}</a>' for key,slug,label,hindi in PAGES)+'</nav>'
 for hi in (False,True):
  for key,slug,label,hindi in PAGES[1:]:
   title,sections=(HI if hi else EN)[key];canonical=url(slug,hi);other=url(slug,not hi)
   seo_title=title+' | ET7' if hi else meta[key]['title'];desc=sections[0][1] if hi else meta[key]['description']
   body=''.join('<section><h2>'+esc(h)+'</h2><p>'+esc(text)+'</p></section>' for h,text in sections)
   if key in ('download','installation'):
    body+='<section class="download-box"><h2>'+('ET7 Android APK' if not hi else 'ET7 Android APK डाउनलोड')+'</h2><p>ET7_2386_2408.apk</p><a class="download" href="'+APK+'">'+('APK डाउनलोड करें' if hi else 'Download ET7 APK')+'</a></section>'
   if key=='installation':body+='<p class="source"><a href="https://support.google.com/android/answer/2812853?hl='+('hi' if hi else 'en')+'">Google Android · Play Protect</a></p>'
   if key=='privacy':body+='<p class="source"><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a></p>'
   breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'ET7','item':origin+'/'},{'@type':'ListItem','position':2,'name':title,'item':canonical}]}
   document=f'''<!doctype html><html lang="{'hi-IN' if hi else 'en-IN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(seo_title)}</title><meta name="description" content="{esc(desc,quote=True)}"><meta name="robots" content="index, follow"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en-IN" href="{url(slug)}"><link rel="alternate" hreflang="hi-IN" href="{url(slug,True)}"><link rel="alternate" hreflang="x-default" href="{url(slug)}"><link rel="icon" href="/global/192.png"><link rel="apple-touch-icon" href="/global/512.png"><meta name="theme-color" content="#181d1b"><meta property="og:type" content="website"><meta property="og:site_name" content="ET7"><meta property="og:title" content="{esc(seo_title,quote=True)}"><meta property="og:description" content="{esc(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{origin}/brand/et7-icon.png"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="/brand/site-pages.css?v=1"><script type="application/ld+json">{json.dumps(breadcrumb,ensure_ascii=False)}</script></head><body class="information-page"><header class="page-header"><a class="page-brand" href="{url('',hi)}"><img src="/brand/et7-icon.png" width="44" height="44" alt="ET7 logo"><b>ET7<span>APK & APP INFORMATION</span></b></a><a class="language" href="{other}" lang="{'en' if hi else 'hi'}">{'English' if hi else 'हिन्दी'} ↗</a></header>{nav(hi)}<main class="page-content"><p class="breadcrumb"><a href="{url('',hi)}">{'होम' if hi else 'Home'}</a> / {esc(hindi if hi else label)}</p><h1>{esc(title)}</h1><p class="lead">{esc(desc)}</p><div class="article-content">{body}</div><aside><h2>{'आगे पढ़ें' if hi else 'Explore more'}</h2>{nav(hi)}</aside></main><footer class="page-footer"><p>© 2026 ET7 · et7ingames.com</p><p>{'वेबसाइट जानकारी और डाउनलोड लिंक' if hi else 'Website information and Android download links'}</p></footer></body></html>'''
   path=site/('hi' if hi else '')/slug;path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(document)
 # Append plain HTML navigation outside the Vue mount so it is crawlable without JavaScript.
 for suffix,hi in [('index.html',False),('hi/index.html',True),('en/index.html',False)]:
  p=site/suffix;s=p.read_text();s=s.replace('</head>','<link rel="stylesheet" href="/brand/site-pages.css?v=1"></head>');s=s.replace('</body>','<div class="home-page-directory"><h2>'+('ET7 पेज' if hi else 'ET7 website pages')+'</h2>'+nav(hi)+'</div></body>');p.write_text(s)
 urls=[url(slug,hi) for hi in (False,True) for _,slug,_,_ in PAGES]
 (site/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
 (Path(__file__).resolve().parents[1]/'docs/indexing-urls.txt').write_text('\n'.join(urls)+'\n')
 print('Generated 7 additional pages per language; 16 canonical URLs in sitemap')
